```matlab
% 生成充放电数据，假设采样率为1kHz，持续时间为10秒钟
fs = 1000; % 采样率
t = linspace(0, 10, 10*fs); % 时间序列

% 电池内阻为100mΩ
R_internal = 0.1;

% 电池起始电量为50%
initial_charge = 50;
voltage = zeros(size(t));
current = zeros(size(t));

% 充电
charging_current = 0.5; % 充电电流为500mA
for i = 2:length(t)
    % 计算电池电压
    voltage(i) = voltage(i-1) + (charging_current - current(i-1)) * R_internal;
    % 计算电池电流
    current(i) = charging_current;
end

% 放电
discharging_current = -0.5; % 放电电流为-500mA
for i = round(length(t)*0.7):length(t)
    % 计算电池电压
    voltage(i) = voltage(i-1) + (discharging_current - current(i-1)) * R_internal;
    % 计算电池电流
    current(i) = discharging_current;
end

% 添加1Hz方波电流激励信号，幅值为500mA
t_start = 3; % 从3秒钟开始添加1Hz方波电流信号
t_end = 5; % 在5秒钟时结束1Hz方波电流信号
pulse_duration = round(1/1*fs); % 1Hz信号的持续时间
pulse_amplitude = 0.5; % 1Hz信号的幅值

% 添加1Hz方波电流信号
for i = round(t_start*fs):round(t_end*fs)
    if mod(i-1, pulse_duration) < pulse_duration/2
        current(i) = current(i) + pulse_amplitude;
    else
        current(i) = current(i) - pulse_amplitude;
    end
end

% 绘制充放电过程中的电压和电流数据
subplot(2,1,1);
plot(t, voltage);
xlabel('Time (s)');
ylabel('Voltage (V)');

subplot(2,1,2);
plot(t, current);
xlabel('Time (s)');
ylabel('Current (A)');

% 保存数据
data = [voltage.' current.'];
save('battery_data.txt', 'data', '-ascii');
```

